export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const FIELDS = new Set(['input', 'steps', 'failAttempts']);
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function isIntIn(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/**
 * Validates a submission. `contentType` and `raw` are the request's Content-Type header and body
 * text; `idempotencyKey` is the Idempotency-Key header when present. Every independently invalid
 * part is reported, so `fields` lists all offending fields.
 */
export function parseSubmission(contentType: string | undefined, raw: string, idempotencyKey: string | undefined): ParseResult {
  const fields: FieldError[] = [];

  if (idempotencyKey !== undefined && !KEY_RE.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return { ok: false, fields };
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  for (const key of Object.keys(parsed)) {
    if (!FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const rawInput = parsed.input;
  if (typeof rawInput !== 'string') {
    fields.push({ field: 'input', message: 'is required and must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (rawInput.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = rawInput;
  }

  let steps = 5;
  if (parsed.steps !== undefined) {
    if (isIntIn(parsed.steps, 1, 20)) steps = parsed.steps;
    else fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  }

  let failAttempts = 0;
  if (parsed.failAttempts !== undefined) {
    if (isIntIn(parsed.failAttempts, 0, 5)) failAttempts = parsed.failAttempts;
    else fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts, idempotencyKey } };
}

