import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
/** A running job whose lease has expired (its worker died) is picked up again. */
const LEASE_MS = 3_000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();

const selectClaimable = db.prepare(`
  SELECT * FROM jobs
  WHERE (status = 'queued' AND next_run_at <= ?) OR (status = 'running' AND lease_until < ?)
  ORDER BY seq ASC
  LIMIT 1
`);
const claimJob = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, lease_until = ?, updated_at = ?
  WHERE id = ?
`);
const setProgress = db.prepare(`
  UPDATE jobs SET completed = ?, lease_until = ?, updated_at = ? WHERE id = ? AND status = 'running'
`);
const completeJob = db.prepare(`
  UPDATE jobs SET status = 'completed', completed = steps, result = ?, error = NULL, lease_until = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const failJob = db.prepare(`
  UPDATE jobs SET status = 'failed', result = NULL, error = 'transient failure', lease_until = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const requeueJob = db.prepare(`
  UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, lease_until = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'
`);
const writeHeartbeat = db.prepare(`
  INSERT INTO heartbeat (name, ts) VALUES ('worker', ?)
  ON CONFLICT(name) DO UPDATE SET ts = excluded.ts
`);

interface Claimed {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempt: number;
}

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Takes the oldest runnable job and marks it running, in one transaction. */
function claim(): Claimed | undefined {
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = selectClaimable.get(now, now) as unknown as JobRow | undefined;
    let claimed: Claimed | undefined;
    if (row) {
      claimJob.run(now + LEASE_MS, new Date(now).toISOString(), row.id);
      claimed = {
        id: row.id,
        input: row.input,
        steps: row.steps,
        failAttempts: row.fail_attempts,
        attempt: row.attempts + 1,
      };
    }
    db.exec('COMMIT');
    return claimed;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

async function runAttempt(job: Claimed): Promise<void> {
  const iso = () => new Date().toISOString();

  if (job.attempt <= job.failAttempts) {
    if (job.attempt >= MAX_ATTEMPTS) failJob.run(iso(), job.id);
    else requeueJob.run(Date.now() + RETRY_DELAY_MS, iso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      // Graceful shutdown: hand the job back so the next worker can start it cleanly.
      requeueJob.run(0, iso(), job.id);
      return;
    }
    await sleep(STEP_MS);
    setProgress.run(step, Date.now() + LEASE_MS, iso(), job.id);
  }
  completeJob.run(job.input.toUpperCase(), iso(), job.id);
}

function heartbeat(): void {
  writeHeartbeat.run(Date.now());
}

